// Strict allowlist for the xb.ac2.arap_alert.v1 event from the AC2 AR/AP aging export (#321 A3).
// Anything outside the closed contract is rejected with a fixed reason code (HTTP 400 to the
// VM); nothing unvalidated reaches the alert email. Request headers are never read or passed on.
// The event carries closed codes only: no party name or code, document number, amount or path.
// The output feeds the closed input of the shared XB Ops Alert Email sub-workflow (#288); the
// call node pins system AC2-ARAP.
const items = $input.all();
const reject = (reason) => [{ json: { valid: false, reason } }];
if (items.length !== 1) return reject('ARAP_ALERT_ITEM_COUNT');
const body = items[0].json && items[0].json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) return reject('ARAP_ALERT_BODY');

const KEYS = ['schema', 'event', 'run_id', 'run_hour_local', 'alert_kind', 'status', 'failure_class', 'conditions', 'delivery_status', 'ap_payments_recorded'];
const CONDITIONS = ['run_failed', 'delivery_failed', 'ap_payments_recorded'];
const KINDS = ['new', 'repeat'];
const FAILURE_CLASSES = ['config_invalid', 'timezone_unavailable', 'already_running', 'stale_lock', 'identity_refused', 'credential_unavailable', 'lock_timeout', 'unstable_snapshot', 'source_error', 'outstanding_mismatch', 'unknown_knockoff_target', 'self_check_failed', 'latest_publish_failed', 'internal_error', 'unknown'];
const DELIVERY_STATUSES = ['not_configured', 'handed_to_drive_sync_folder', 'verify_failed', 'copy_failed', 'skipped_failed_run'];
const DELIVERY_FAILURES = ['verify_failed', 'copy_failed'];
const WARN_CONDITIONS = ['ap_payments_recorded'];

const keys = Object.keys(body);
if (keys.length !== KEYS.length || !KEYS.every((key) => keys.includes(key))) return reject('ARAP_ALERT_KEYS');
if (body.schema !== 'xb.ac2.arap_alert.v1') return reject('ARAP_ALERT_SCHEMA');
if (body.event !== 'ac2_arap_alert') return reject('ARAP_ALERT_EVENT');
if (typeof body.run_id !== 'string' || !/^([0-9a-f]{32}|unknown)$/.test(body.run_id)) return reject('ARAP_ALERT_RUN_ID');
if (typeof body.run_hour_local !== 'string' || !/^\d{4}-\d\d-\d\dT\d\d:00:00[+-]\d\d:\d\d$/.test(body.run_hour_local)) return reject('ARAP_ALERT_HOUR');
if (!KINDS.includes(body.alert_kind)) return reject('ARAP_ALERT_KIND');
if (body.status !== 'success' && body.status !== 'failed') return reject('ARAP_ALERT_STATUS');
const failed = body.status === 'failed';
if (failed ? !FAILURE_CLASSES.includes(body.failure_class) : body.failure_class !== null) return reject('ARAP_ALERT_FAILURE_CLASS');
const conditions = body.conditions;
if (!Array.isArray(conditions) || conditions.length === 0 || conditions.length > CONDITIONS.length) return reject('ARAP_ALERT_CONDITIONS');
if (new Set(conditions).size !== conditions.length || !conditions.every((c) => CONDITIONS.includes(c))) return reject('ARAP_ALERT_CONDITIONS');
if (failed ? !(conditions.length === 1 && conditions[0] === 'run_failed') : conditions.includes('run_failed')) return reject('ARAP_ALERT_CONDITIONS');
if (body.delivery_status !== null && !DELIVERY_STATUSES.includes(body.delivery_status)) return reject('ARAP_ALERT_DELIVERY_STATUS');
if (conditions.includes('delivery_failed') !== DELIVERY_FAILURES.includes(body.delivery_status)) return reject('ARAP_ALERT_DELIVERY_STATUS');
const ap = body.ap_payments_recorded;
if (failed ? ap !== null : typeof ap !== 'boolean') return reject('ARAP_ALERT_AP_FLAG');
if (conditions.includes('ap_payments_recorded') !== (ap === true)) return reject('ARAP_ALERT_AP_FLAG');

// Plain-text email: every value above is from a closed set, so no escaping is needed. The
// subject code is stable per condition set (no time), so repeats share one thread.
const active = CONDITIONS.filter((c) => conditions.includes(c));
const severity = active.every((c) => WARN_CONDITIONS.includes(c)) ? 'WARN' : 'ERROR';
const short = failed ? 'run_failed:' + body.failure_class : active.join('+');
const LABELS = {
  run_failed: 'Hourly AR/AP export FAILED: ' + body.failure_class + ' (nothing new published; Drive keeps the last good set)',
  delivery_failed: 'Drive delivery failed: ' + body.delivery_status + ' (Drive keeps the previous set; the next run retries)',
  ap_payments_recorded: 'AP payments are now recorded in AutoCount: check knockoff_target_types.ap and rerun the V3 creditor compare before relying on AP figures (sent once)',
};
const lines = [
  body.alert_kind === 'repeat' ? 'AC2 AR/AP export: still not resolved (daily reminder)' : 'AC2 AR/AP export: ' + severity,
  '',
  ...active.map((c) => '- ' + LABELS[c]),
  '',
  'Hour: ' + body.run_hour_local.slice(0, 16).replace('T', ' ') + ' (UTC' + body.run_hour_local.slice(19) + ')',
  'Run: ' + body.run_id.slice(0, 8),
  'Details: last_run_status.json in the Drive folder; runbook docs/autocount2-automation/arap_aging_runbook.md, section "Failure classes".',
];
return [{ json: { valid: true, severity, key: short, short, lines } }];
